// MCPlex — Audit Logger
// Structured JSON audit logging with automatic file rotation

use std::io::Write;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;
// v0.4.0: Removed SystemTime/UNIX_EPOCH imports (now delegated to util.rs)
use tracing::{error, info};

use crate::protocol::ToolCallParams;

/// Structured audit logger with automatic log rotation
pub struct AuditLogger {
    log_path: String,
    writer: Mutex<Option<std::io::BufWriter<std::fs::File>>>,
    /// Current file size in bytes (approximate)
    current_size: AtomicU64,
    /// Maximum file size in bytes before rotation
    max_size_bytes: u64,
}

/// Audit log entry
#[derive(serde::Serialize)]
struct AuditEntry {
    timestamp: String,
    event: String,
    tool_name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    server_name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    arguments: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    duration_ms: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    reason: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    trace_id: Option<String>,
}

impl AuditLogger {
    /// Convenience constructor with the default 100 MB rotation limit.
    /// Kept as public API surface for embedding MCPlex as a library.
    #[allow(dead_code)]
    pub fn new(log_path: &str, enabled: bool) -> Self {
        Self::with_max_size(log_path, enabled, 100) // Default 100 MB
    }

    pub fn with_max_size(log_path: &str, enabled: bool, max_size_mb: u64) -> Self {
        let (writer, current_size) = if enabled {
            match Self::open_log_file(log_path) {
                Ok(w) => {
                    let size = std::fs::metadata(log_path).map(|m| m.len()).unwrap_or(0);
                    info!(
                        "📝 Audit log: {} (max {}MB, current {:.1}MB)",
                        log_path,
                        max_size_mb,
                        size as f64 / 1_048_576.0
                    );
                    (Mutex::new(Some(w)), AtomicU64::new(size))
                }
                Err(e) => {
                    error!(
                        "Failed to open audit log '{}': {} — audit logging disabled",
                        log_path, e
                    );
                    (Mutex::new(None), AtomicU64::new(0))
                }
            }
        } else {
            (Mutex::new(None), AtomicU64::new(0))
        };

        Self {
            log_path: log_path.to_string(),
            writer,
            current_size,
            max_size_bytes: max_size_mb * 1_048_576,
        }
    }

    fn open_log_file(path: &str) -> anyhow::Result<std::io::BufWriter<std::fs::File>> {
        if let Some(parent) = std::path::Path::new(path).parent() {
            std::fs::create_dir_all(parent)?;
        }
        let file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(std::io::BufWriter::new(file))
    }

    /// Rotate the log file when it exceeds max size
    fn rotate_if_needed(&self) {
        let size = self.current_size.load(Ordering::Relaxed);
        if size < self.max_size_bytes {
            return;
        }

        // Rotate: rename current file to .1, .2, etc. (keep up to 5 rotations)
        if let Ok(mut guard) = self.writer.lock() {
            // Double-check inside lock
            if self.current_size.load(Ordering::Relaxed) < self.max_size_bytes {
                return;
            }

            info!(
                "🔄 Rotating audit log ({:.1}MB >= {}MB limit)",
                size as f64 / 1_048_576.0,
                self.max_size_bytes / 1_048_576
            );

            // Flush and close current writer
            if let Some(ref mut w) = *guard {
                let _ = w.flush();
            }
            *guard = None;

            // Shift existing rotated files (.4 → .5, .3 → .4, etc.)
            for i in (1..5).rev() {
                let from = format!("{}.{}", self.log_path, i);
                let to = format!("{}.{}", self.log_path, i + 1);
                let _ = std::fs::rename(&from, &to);
            }

            // Rename current to .1
            let rotated = format!("{}.1", self.log_path);
            let _ = std::fs::rename(&self.log_path, &rotated);

            // Delete oldest (keep 5 rotations max)
            let oldest = format!("{}.5", self.log_path);
            let _ = std::fs::remove_file(&oldest);

            // Open fresh file
            match Self::open_log_file(&self.log_path) {
                Ok(w) => {
                    *guard = Some(w);
                    self.current_size.store(0, Ordering::Relaxed);
                    info!("✅ Audit log rotated successfully");
                }
                Err(e) => {
                    error!("Failed to open new audit log after rotation: {}", e);
                }
            }
        }
    }

    pub fn log_tool_call(
        &self,
        tool_name: &str,
        server_name: &str,
        params: &ToolCallParams,
        duration_ms: u64,
    ) {
        let entry = AuditEntry {
            timestamp: now_iso8601(),
            event: "tool_call".to_string(),
            tool_name: tool_name.to_string(),
            server_name: Some(server_name.to_string()),
            arguments: params.arguments.as_ref().map(redact_sensitive),
            duration_ms: Some(duration_ms),
            reason: None,
            trace_id: Some(uuid::Uuid::new_v4().to_string()),
        };

        self.write_entry(&entry);
    }

    /// Record a non-tool access event (resources/read, prompts/get).
    pub fn log_access(&self, event: &str, target: &str, duration_ms: u64) {
        let entry = AuditEntry {
            timestamp: now_iso8601(),
            event: event.to_string(),
            tool_name: target.to_string(),
            server_name: None,
            arguments: None,
            duration_ms: Some(duration_ms),
            reason: None,
            trace_id: Some(uuid::Uuid::new_v4().to_string()),
        };

        self.write_entry(&entry);
    }

    pub fn log_blocked_call(&self, tool_name: &str, reason: &str) {
        let entry = AuditEntry {
            timestamp: now_iso8601(),
            event: "tool_blocked".to_string(),
            tool_name: tool_name.to_string(),
            server_name: None,
            arguments: None,
            duration_ms: None,
            reason: Some(reason.to_string()),
            trace_id: Some(uuid::Uuid::new_v4().to_string()),
        };

        self.write_entry(&entry);
    }

    fn write_entry(&self, entry: &AuditEntry) {
        // Check rotation before writing
        self.rotate_if_needed();

        if let Ok(json) = serde_json::to_string(entry) {
            let line_size = json.len() as u64 + 1; // +1 for newline
            if let Ok(mut guard) = self.writer.lock() {
                if let Some(ref mut writer) = *guard {
                    let _ = writeln!(writer, "{}", json);
                    let _ = writer.flush();
                    self.current_size.fetch_add(line_size, Ordering::Relaxed);
                }
            }
        }
    }
}

/// Generate ISO 8601 timestamp without chrono dependency
/// v0.4.0: Delegates to shared util::now_iso8601() to eliminate duplication
fn now_iso8601() -> String {
    crate::util::now_iso8601()
}

/// Key substrings considered sensitive — values under matching keys are
/// replaced with "[REDACTED]" before being written to the audit log so
/// credentials never persist to disk.
const SENSITIVE_KEY_PARTS: &[&str] = &[
    "password",
    "passwd",
    "pwd",
    "secret",
    "token",
    "api_key",
    "apikey",
    "authorization",
    "auth",
    "credential",
    "private_key",
    "access_key",
    "cookie",
    "session",
    "bearer",
];

/// Recursively redact values whose keys look sensitive.
fn redact_sensitive(value: &serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Object(map) => {
            let redacted = map
                .iter()
                .map(|(k, v)| {
                    let key_lower = k.to_lowercase();
                    if SENSITIVE_KEY_PARTS.iter().any(|s| key_lower.contains(s)) {
                        (k.clone(), serde_json::Value::String("[REDACTED]".into()))
                    } else {
                        (k.clone(), redact_sensitive(v))
                    }
                })
                .collect();
            serde_json::Value::Object(redacted)
        }
        serde_json::Value::Array(items) => {
            serde_json::Value::Array(items.iter().map(redact_sensitive).collect())
        }
        other => other.clone(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read;

    #[test]
    fn test_audit_logger_writes_entries() {
        let temp_dir = std::env::temp_dir().join("mcplex_test_audit");
        let _ = std::fs::create_dir_all(&temp_dir);
        let log_path = temp_dir.join("test_audit.jsonl");
        let log_path_str = log_path.to_str().unwrap();
        let _ = std::fs::remove_file(&log_path);

        let logger = AuditLogger::new(log_path_str, true);

        let params = ToolCallParams {
            name: "test_tool".to_string(),
            arguments: Some(serde_json::json!({"key": "value"})),
        };

        logger.log_tool_call("test_tool", "test_server", &params, 42);
        logger.log_blocked_call("blocked_tool", "security_policy");

        let mut content = String::new();
        std::fs::File::open(&log_path)
            .unwrap()
            .read_to_string(&mut content)
            .unwrap();

        let lines: Vec<&str> = content.trim().lines().collect();
        assert_eq!(lines.len(), 2);

        let entry1: serde_json::Value = serde_json::from_str(lines[0]).unwrap();
        assert_eq!(entry1["event"], "tool_call");
        assert_eq!(entry1["tool_name"], "test_tool");

        let entry2: serde_json::Value = serde_json::from_str(lines[1]).unwrap();
        assert_eq!(entry2["event"], "tool_blocked");

        let _ = std::fs::remove_file(&log_path);
        let _ = std::fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_redact_sensitive_keys() {
        let input = serde_json::json!({
            "username": "alice",
            "password": "hunter2",
            "config": {
                "api_key": "sk-12345",
                "GitHub_Token": "ghp_abc",
                "timeout": 30
            },
            "items": [{"secret_value": "x", "name": "ok"}]
        });

        let redacted = redact_sensitive(&input);

        assert_eq!(redacted["username"], "alice");
        assert_eq!(redacted["password"], "[REDACTED]");
        assert_eq!(redacted["config"]["api_key"], "[REDACTED]");
        assert_eq!(redacted["config"]["GitHub_Token"], "[REDACTED]");
        assert_eq!(redacted["config"]["timeout"], 30);
        assert_eq!(redacted["items"][0]["secret_value"], "[REDACTED]");
        assert_eq!(redacted["items"][0]["name"], "ok");
    }

    #[test]
    fn test_tool_call_audit_redacts_arguments() {
        let temp_dir = std::env::temp_dir().join("mcplex_test_audit_redact");
        let _ = std::fs::create_dir_all(&temp_dir);
        let log_path = temp_dir.join("test_redact.jsonl");
        let log_path_str = log_path.to_str().unwrap();
        let _ = std::fs::remove_file(&log_path);

        let logger = AuditLogger::new(log_path_str, true);
        let params = ToolCallParams {
            name: "login".to_string(),
            arguments: Some(serde_json::json!({"user": "bob", "password": "pw"})),
        };
        logger.log_tool_call("login", "auth_server", &params, 5);

        let mut content = String::new();
        std::fs::File::open(&log_path)
            .unwrap()
            .read_to_string(&mut content)
            .unwrap();

        let entry: serde_json::Value = serde_json::from_str(content.trim()).unwrap();
        assert_eq!(entry["arguments"]["user"], "bob");
        assert_eq!(entry["arguments"]["password"], "[REDACTED]");

        let _ = std::fs::remove_file(&log_path);
        let _ = std::fs::remove_dir(&temp_dir);
    }
}

// MCPlex — Security Engine
// RBAC, audit logging, and tool allowlist/blocklist enforcement

pub mod allowlist;
pub mod audit;
pub mod rbac;

use crate::config::AppConfig;
use crate::protocol::ToolCallParams;

/// Combined security engine
pub struct SecurityEngine {
    rbac: rbac::RbacEngine,
    audit: audit::AuditLogger,
    allowlist: allowlist::AllowlistEngine,
    rbac_enabled: bool,
    audit_enabled: bool,
}

impl SecurityEngine {
    pub fn new(config: &AppConfig) -> Self {
        Self {
            rbac: rbac::RbacEngine::new(&config.roles),
            audit: audit::AuditLogger::with_max_size(
                &config.security.audit_log_path,
                config.security.enable_audit_log,
                config.security.max_log_size_mb,
            ),
            allowlist: allowlist::AllowlistEngine::new(&config.servers),
            rbac_enabled: config.security.enable_rbac,
            audit_enabled: config.security.enable_audit_log,
        }
    }

    /// Check if a tool is allowed for a given role
    pub fn is_tool_allowed(&self, tool_fqn: &str, role: Option<&str>) -> bool {
        // Check allowlist first
        if !self.allowlist.is_allowed(tool_fqn) {
            return false;
        }

        // Check RBAC if enabled
        if self.rbac_enabled {
            if let Some(role) = role {
                return self.rbac.is_allowed(role, tool_fqn);
            }
            // v0.4.0: RBAC enabled but no role provided — deny by default
            // for security. Clients must provide a valid role via API key
            // mapping or the request will be rejected.
            return false;
        }

        true
    }

    /// Record an audit log entry for a tool call
    pub fn audit_tool_call(
        &self,
        tool_name: &str,
        server_name: &str,
        params: &ToolCallParams,
        duration_ms: u64,
    ) {
        if self.audit_enabled {
            self.audit
                .log_tool_call(tool_name, server_name, params, duration_ms);
        }
    }

    /// Record an audit log entry for a blocked call
    pub fn audit_blocked_call(&self, tool_name: &str, reason: &str) {
        if self.audit_enabled {
            self.audit.log_blocked_call(tool_name, reason);
        }
    }

    /// Record an audit log entry for a resource read or prompt fetch
    pub fn audit_access(&self, event: &str, target: &str, duration_ms: u64) {
        if self.audit_enabled {
            self.audit.log_access(event, target, duration_ms);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::RoleConfig;

    fn rbac_config_with_admin_role() -> AppConfig {
        let mut config: AppConfig =
            toml::from_str("[gateway]\n").expect("minimal config with defaults must parse");
        config.security.enable_rbac = true;
        config.roles.insert(
            "admin".to_string(),
            RoleConfig {
                allowed_tools: vec!["*".to_string()],
                blocked_tools: vec![],
            },
        );
        config
    }

    /// Regression test: RBAC must deny when no server-verified role is
    /// established, even though an "admin" (allow-all) role exists in
    /// config. This guards the fix that removed the client-controlled
    /// `_mcplex_role` params fallback in `dispatch_real_tool` — a client
    /// could previously self-assert `role: "admin"` and bypass RBAC
    /// whenever no api_key/api_keys were configured.
    #[test]
    fn rbac_denies_when_no_trusted_role_established() {
        let config = rbac_config_with_admin_role();
        let engine = SecurityEngine::new(&config);
        assert!(!engine.is_tool_allowed("some_tool", None));
    }

    #[test]
    fn rbac_allows_with_a_trusted_role() {
        let config = rbac_config_with_admin_role();
        let engine = SecurityEngine::new(&config);
        assert!(engine.is_tool_allowed("some_tool", Some("admin")));
    }
}

// MCPlex — Role-Based Access Control
// Maps roles to tool permissions using glob patterns

use crate::config::RoleConfig;
use std::collections::HashMap;

/// RBAC engine for tool access control
pub struct RbacEngine {
    roles: HashMap<String, RoleConfig>,
}

impl RbacEngine {
    pub fn new(roles: &HashMap<String, RoleConfig>) -> Self {
        Self {
            roles: roles.clone(),
        }
    }

    /// Check if a role is allowed to access a tool
    pub fn is_allowed(&self, role: &str, tool_fqn: &str) -> bool {
        if let Some(role_config) = self.roles.get(role) {
            // Check blocklist first (takes precedence)
            for pattern in &role_config.blocked_tools {
                if glob_match(pattern, tool_fqn) {
                    return false;
                }
            }

            // If allowlist is empty, allow everything
            if role_config.allowed_tools.is_empty() {
                return true;
            }

            // Check allowlist
            for pattern in &role_config.allowed_tools {
                if glob_match(pattern, tool_fqn) {
                    return true;
                }
            }

            false
        } else {
            // Unknown role — deny by default
            false
        }
    }

    /// List all roles
    #[allow(dead_code)]
    pub fn list_roles(&self) -> Vec<String> {
        self.roles.keys().cloned().collect()
    }
}

// v0.4.0: Use shared glob_match from util.rs (was duplicated in rbac.rs and allowlist.rs)
use crate::util::glob_match;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_glob_match() {
        assert!(glob_match("*", "anything"));
        assert!(glob_match("github/*", "github/create_issue"));
        assert!(glob_match("github/*", "github/list_repos"));
        assert!(!glob_match("github/*", "slack/send_message"));
        assert!(glob_match("*/query_*", "database/query_users"));
        assert!(glob_match("?ello", "hello"));
        assert!(!glob_match("?ello", "jello_world"));
        assert!(glob_match("delete_*", "delete_users"));
        assert!(glob_match("delete_*", "delete_everything"));
    }

    #[test]
    fn test_rbac() {
        let mut roles = HashMap::new();
        roles.insert(
            "developer".to_string(),
            RoleConfig {
                allowed_tools: vec!["github/*".to_string(), "database/query_*".to_string()],
                blocked_tools: vec![],
            },
        );
        roles.insert(
            "admin".to_string(),
            RoleConfig {
                allowed_tools: vec!["*".to_string()],
                blocked_tools: vec![],
            },
        );
        roles.insert(
            "readonly".to_string(),
            RoleConfig {
                allowed_tools: vec!["*/list_*".to_string(), "*/get_*".to_string()],
                blocked_tools: vec!["*/delete_*".to_string()],
            },
        );

        let engine = RbacEngine::new(&roles);

        // Developer role
        assert!(engine.is_allowed("developer", "github/create_issue"));
        assert!(engine.is_allowed("developer", "database/query_users"));
        assert!(!engine.is_allowed("developer", "slack/send_message"));

        // Admin role
        assert!(engine.is_allowed("admin", "anything/at_all"));

        // Readonly role
        assert!(engine.is_allowed("readonly", "github/list_repos"));
        assert!(engine.is_allowed("readonly", "database/get_user"));
        assert!(!engine.is_allowed("readonly", "database/delete_user"));

        // Unknown role
        assert!(!engine.is_allowed("unknown", "anything"));
    }
}

// MCPlex — Allowlist/Blocklist Engine
// Per-server tool filtering based on configuration

use crate::config::ServerConfig;

/// Engine for enforcing tool allow/block lists per server
pub struct AllowlistEngine {
    rules: Vec<ServerToolRule>,
}

struct ServerToolRule {
    server_name: String,
    allowed_tools: Vec<String>,
    blocked_tools: Vec<String>,
}

impl AllowlistEngine {
    pub fn new(servers: &[ServerConfig]) -> Self {
        let rules = servers
            .iter()
            .map(|s| ServerToolRule {
                server_name: s.name.clone(),
                allowed_tools: s.allowed_tools.clone(),
                blocked_tools: s.blocked_tools.clone(),
            })
            .collect();

        Self { rules }
    }

    /// Check if a tool is allowed by the allowlist/blocklist rules
    pub fn is_allowed(&self, tool_fqn: &str) -> bool {
        // Parse the FQN into server/tool parts
        let (server, tool) = if let Some(pos) = tool_fqn.find('/') {
            (&tool_fqn[..pos], &tool_fqn[pos + 1..])
        } else {
            // If no server prefix, check tool name against all rules
            ("", tool_fqn)
        };

        for rule in &self.rules {
            // Only check rules for the matching server
            if !server.is_empty() && rule.server_name != server {
                continue;
            }

            // Check blocklist first (takes precedence)
            for pattern in &rule.blocked_tools {
                if glob_match(pattern, tool) || glob_match(pattern, tool_fqn) {
                    return false;
                }
            }

            // If allowlist is defined, tool must match at least one pattern
            if !rule.allowed_tools.is_empty() {
                let allowed = rule
                    .allowed_tools
                    .iter()
                    .any(|pattern| glob_match(pattern, tool) || glob_match(pattern, tool_fqn));
                if !allowed && (server == rule.server_name || server.is_empty()) {
                    return false;
                }
            }
        }

        true
    }
}

