// MCPlex — AgentLens Bridge
// Optional, non-blocking forwarder that sends tool call events to AgentLens
// for visualization in the timeline replay UI.
//
// This module is entirely opt-in. If [agentlens] is missing from the config
// or enabled=false, the bridge is never instantiated and MCPlex works exactly
// as it always has — zero overhead, zero coupling.

use crate::config::AgentLensConfig;
use serde_json::json;
use std::sync::Arc;
use tracing::{debug, info};
use uuid::Uuid;

/// Non-blocking forwarder that sends events to AgentLens.
/// All HTTP calls are fire-and-forget on a background task —
/// they never block the gateway's critical path.
pub struct AgentLensBridge {
    config: AgentLensConfig,
    client: reqwest::Client,
    session_id: String,
}

impl AgentLensBridge {
    /// Create a new bridge. Returns None if the config is disabled.
    pub fn new(config: &AgentLensConfig) -> Option<Arc<Self>> {
        if !config.enabled {
            return None;
        }

        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(5))
            .build()
            .ok()?;

        let session_id = Uuid::new_v4().to_string();

        info!(
            "🔗 AgentLens bridge enabled → forwarding events to {}",
            config.url
        );
        info!("   Session ID: {}", session_id);
        info!("   Session name: {}", config.session_name);

        Some(Arc::new(Self {
            config: config.clone(),
            client,
            session_id,
        }))
    }

    /// Forward a tool call event to AgentLens (fire-and-forget).
    pub fn forward_tool_call(
        self: &Arc<Self>,
        tool_name: &str,
        server_name: &str,
        duration_ms: u64,
        success: bool,
    ) {
        if !self.config.forward_tool_calls {
            return;
        }

        let payload = json!({
            "session_id": self.session_id,
            "session_name": self.config.session_name,
            "agent_name": format!("MCPlex/{}", server_name),
            "step_type": "mcp_invoke",
            "status": if success { "success" } else { "error" },
            "mcp_server": server_name,
            "mcp_tool": tool_name,
            "mcp_params": {},
            "duration_ms": duration_ms,
        });

        let client = self.client.clone();
        let url = self.config.url.clone();
        let tool_name_owned = tool_name.to_string();

        // Fire-and-forget: spawn a background task, don't await
        tokio::spawn(async move {
            match client.post(&url).json(&payload).send().await {
                Ok(resp) if resp.status().is_success() => {
                    debug!("🔗 AgentLens: forwarded tool_call {}", tool_name_owned);
                }
                Ok(resp) => {
                    debug!("🔗 AgentLens: forward returned status {}", resp.status());
                }
                Err(e) => {
                    // AgentLens might be offline — that's fine, don't spam logs
                    debug!("🔗 AgentLens: forward failed (offline?): {}", e);
                }
            }
        });
    }

    /// Forward a security event (RBAC block, rate limit) to AgentLens.
    pub fn forward_security_event(
        self: &Arc<Self>,
        event_type: &str,
        tool_name: &str,
        reason: &str,
    ) {
        if !self.config.forward_security_events {
            return;
        }

        let payload = json!({
            "session_id": self.session_id,
            "session_name": self.config.session_name,
            "agent_name": "MCPlex/Security",
            "step_type": "error",
            "status": "error",
            "error_message": format!("{}: {} ({})", event_type, tool_name, reason),
            "error_type": event_type,
            "duration_ms": 0,
        });

        let client = self.client.clone();
        let url = self.config.url.clone();

        tokio::spawn(async move {
            let _ = client.post(&url).json(&payload).send().await;
        });
    }

    /// Forward a routing/discovery event to AgentLens.
    pub fn forward_routing_event(
        self: &Arc<Self>,
        query: &str,
        total_tools: usize,
        selected_tools: usize,
    ) {
        let payload = json!({
            "session_id": self.session_id,
            "session_name": self.config.session_name,
            "agent_name": "MCPlex/Router",
            "step_type": "decision",
            "decision_reason": format!(
                "Routing query '{}': {} → {} tools (saved {} tool definitions)",
                query, total_tools, selected_tools, total_tools - selected_tools
            ),
            "duration_ms": 0,
        });

        let client = self.client.clone();
        let url = self.config.url.clone();

        tokio::spawn(async move {
            let _ = client.post(&url).json(&payload).send().await;
        });
    }
}

// MCPlex — Tool Response Cache
// Caches idempotent tool responses to reduce upstream calls and latency

use std::collections::HashMap;
use std::sync::RwLock;
use std::time::{Duration, Instant};
use tracing::debug;

/// A time-based cache for tool call responses
pub struct ToolCache {
    entries: RwLock<HashMap<String, CacheEntry>>,
    /// Default TTL for cached responses
    default_ttl: Duration,
    /// Maximum number of cached entries
    max_entries: usize,
    /// Tools that should be cached (glob patterns)
    cacheable_patterns: Vec<String>,
}

struct CacheEntry {
    value: serde_json::Value,
    inserted_at: Instant,
    ttl: Duration,
    hits: u64,
}

impl CacheEntry {
    fn is_expired(&self) -> bool {
        self.inserted_at.elapsed() > self.ttl
    }
}

impl ToolCache {
    pub fn new(ttl_seconds: u64, max_entries: usize, patterns: Vec<String>) -> Self {
        Self {
            entries: RwLock::new(HashMap::new()),
            default_ttl: Duration::from_secs(ttl_seconds),
            max_entries,
            cacheable_patterns: patterns,
        }
    }

    /// Check if a tool call result is cached and still valid
    pub fn get(
        &self,
        tool_name: &str,
        role: Option<&str>,
        arguments: &Option<serde_json::Value>,
    ) -> Option<serde_json::Value> {
        if !self.is_cacheable(tool_name) {
            return None;
        }

        let key = Self::cache_key(tool_name, role, arguments);

        if let Ok(mut entries) = self.entries.write() {
            if let Some(entry) = entries.get_mut(&key) {
                if !entry.is_expired() {
                    entry.hits += 1;
                    debug!("📦 Cache HIT: {} ({}x)", tool_name, entry.hits);
                    return Some(entry.value.clone());
                } else {
                    // Remove expired entry
                    entries.remove(&key);
                }
            }
        }

        None
    }

    /// Store a tool call result in the cache
    pub fn put(
        &self,
        tool_name: &str,
        role: Option<&str>,
        arguments: &Option<serde_json::Value>,
        value: serde_json::Value,
    ) {
        if !self.is_cacheable(tool_name) {
            return;
        }

        let key = Self::cache_key(tool_name, role, arguments);

        if let Ok(mut entries) = self.entries.write() {
            // Evict if at capacity — remove oldest expired entries first
            if entries.len() >= self.max_entries {
                let expired_keys: Vec<String> = entries
                    .iter()
                    .filter(|(_, v)| v.is_expired())
                    .map(|(k, _)| k.clone())
                    .collect();
                for key in expired_keys {
                    entries.remove(&key);
                }

                // If still at capacity, remove oldest entry
                if entries.len() >= self.max_entries {
                    if let Some(oldest_key) = entries
                        .iter()
                        .min_by_key(|(_, v)| v.inserted_at)
                        .map(|(k, _)| k.clone())
                    {
                        entries.remove(&oldest_key);
                    }
                }
            }

            entries.insert(
                key,
                CacheEntry {
                    value,
                    inserted_at: Instant::now(),
                    ttl: self.default_ttl,
                    hits: 0,
                },
            );
        }
    }

    /// Invalidate all cache entries for a specific tool
    pub fn invalidate(&self, tool_name: &str) {
        if let Ok(mut entries) = self.entries.write() {
            let prefix = format!("{}:", tool_name);
            entries.retain(|k, _| !k.starts_with(&prefix));
        }
    }

    /// Invalidate the entire cache
    pub fn invalidate_all(&self) {
        if let Ok(mut entries) = self.entries.write() {
            entries.clear();
        }
    }

    /// Get cache statistics
    pub fn stats(&self) -> CacheStats {
        if let Ok(entries) = self.entries.read() {
            let total = entries.len();
            let expired = entries.values().filter(|e| e.is_expired()).count();
            let total_hits: u64 = entries.values().map(|e| e.hits).sum();
            CacheStats {
                total_entries: total,
                expired_entries: expired,
                total_hits,
            }
        } else {
            CacheStats {
                total_entries: 0,
                expired_entries: 0,
                total_hits: 0,
            }
        }
    }

    /// Check if a tool should be cached based on patterns
    fn is_cacheable(&self, tool_name: &str) -> bool {
        if self.cacheable_patterns.is_empty() {
            // Default: cache read-only tools (list_*, get_*, search_*, query_*, describe_*, show_*)
            let read_prefixes = [
                "list_",
                "get_",
                "search_",
                "query_",
                "describe_",
                "show_",
                "count_",
                "check_",
            ];
            return read_prefixes.iter().any(|p| tool_name.starts_with(p));
        }

        self.cacheable_patterns.iter().any(|pattern| {
            glob::Pattern::new(pattern)
                .map(|p| p.matches(tool_name))
                .unwrap_or(false)
        })
    }

    /// Generate a deterministic cache key from tool name + caller role + arguments.
    /// Partitioning by role prevents a cached response fetched under one
    /// API key/role from leaking to a caller with a different identity in
    /// multi-tenant deployments. `tool_name` stays the leading segment so
    /// `invalidate()`'s prefix match still works across all roles.
    fn cache_key(
        tool_name: &str,
        role: Option<&str>,
        arguments: &Option<serde_json::Value>,
    ) -> String {
        match arguments {
            Some(args) => format!(
                "{}:{}:{}",
                tool_name,
                role.unwrap_or(""),
                serde_json::to_string(args).unwrap_or_default()
            ),
            None => format!("{}:{}:()", tool_name, role.unwrap_or("")),
        }
    }
}

#[derive(Debug, Clone)]
pub struct CacheStats {
    pub total_entries: usize,
    pub expired_entries: usize,
    pub total_hits: u64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cache_hit_miss() {
        let cache = ToolCache::new(60, 100, vec![]);

        // list_ prefix is auto-cacheable
        let args = Some(serde_json::json!({"filter": "active"}));

        // Miss
        assert!(cache.get("list_tables", None, &args).is_none());

        // Put
        let result = serde_json::json!({"tables": ["users", "orders"]});
        cache.put("list_tables", None, &args, result.clone());

        // Hit
        let cached = cache.get("list_tables", None, &args);
        assert!(cached.is_some());
        assert_eq!(cached.unwrap(), result);
    }

    #[test]
    fn test_non_cacheable_tools() {
        let cache = ToolCache::new(60, 100, vec![]);

        // create_ prefix is NOT auto-cacheable
        let args = Some(serde_json::json!({"name": "test"}));
        let result = serde_json::json!({"id": 1});

        cache.put("create_issue", None, &args, result);
        assert!(cache.get("create_issue", None, &args).is_none());
    }

    #[test]
    fn test_cache_expiration() {
        let cache = ToolCache::new(0, 100, vec![]); // 0 second TTL

        let args = None;
        cache.put("list_tables", None, &args, serde_json::json!({}));

        // Should be expired immediately
        std::thread::sleep(std::time::Duration::from_millis(10));
        assert!(cache.get("list_tables", None, &args).is_none());
    }

    #[test]
    fn test_custom_patterns() {
        let cache = ToolCache::new(60, 100, vec!["my_tool".to_string(), "custom_*".to_string()]);

        let args = None;
        let val = serde_json::json!("ok");

        // Exact match
        cache.put("my_tool", None, &args, val.clone());
        assert!(cache.get("my_tool", None, &args).is_some());

        // Glob match
        cache.put("custom_query", None, &args, val.clone());
        assert!(cache.get("custom_query", None, &args).is_some());

        // Non-match (list_ wouldn't match with custom patterns set)
        cache.put("list_tables", None, &args, val);
        assert!(cache.get("list_tables", None, &args).is_none());
    }

    #[test]
    fn test_invalidation() {
        let cache = ToolCache::new(60, 100, vec![]);

        cache.put("list_tables", None, &None, serde_json::json!({"a": 1}));
        cache.put("list_repos", None, &None, serde_json::json!({"b": 2}));

        cache.invalidate("list_tables");
        assert!(cache.get("list_tables", None, &None).is_none());
        assert!(cache.get("list_repos", None, &None).is_some());
    }

    #[test]
    fn test_role_partitioned_cache() {
        let cache = ToolCache::new(60, 100, vec![]);
        let args = Some(serde_json::json!({"id": 1}));

        // tenant "admin" stores a result...
        cache.put(
            "get_record",
            Some("admin"),
            &args,
            serde_json::json!({"secret": true}),
        );

        // ...a different role with the same tool+args must NOT see it
        assert!(cache.get("get_record", Some("viewer"), &args).is_none());
        // the same role does see its own cached result
        assert!(cache.get("get_record", Some("admin"), &args).is_some());
    }
}

// MCPlex — Shared Utilities
// Common functions used across the codebase to avoid duplication.
// v0.4.0: Extracted from rbac.rs and allowlist.rs to eliminate code duplication.

/// Match a pattern against a string using glob-style matching.
/// Supports `*` (match any sequence of characters) and `?` (match a single character).
pub fn glob_match(pattern: &str, text: &str) -> bool {
    let pattern_chars: Vec<char> = pattern.chars().collect();
    let text_chars: Vec<char> = text.chars().collect();
    glob_match_recursive(&pattern_chars, &text_chars, 0, 0)
}

fn glob_match_recursive(pattern: &[char], text: &[char], pi: usize, ti: usize) -> bool {
    if pi == pattern.len() && ti == text.len() {
        return true;
    }
    if pi == pattern.len() {
        return false;
    }
    if pattern[pi] == '*' {
        // Match zero or more characters
        for i in ti..=text.len() {
            if glob_match_recursive(pattern, text, pi + 1, i) {
                return true;
            }
        }
        return false;
    }
    if ti == text.len() {
        return false;
    }
    if pattern[pi] == '?' || pattern[pi] == text[ti] {
        return glob_match_recursive(pattern, text, pi + 1, ti + 1);
    }
    false
}

/// Generate ISO 8601 timestamp without chrono dependency.
/// v0.4.0: Extracted from metrics.rs and audit.rs to eliminate duplication.
pub fn now_iso8601() -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs();
    // Rough UTC breakdown (not accounting for leap seconds, but good enough for logging)
    let days = secs / 86400;
    let remaining_secs = secs % 86400;
    let hours = remaining_secs / 3600;
    let minutes = (remaining_secs % 3600) / 60;
    let seconds = remaining_secs % 60;

    let (year, month, day) = days_to_ymd(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        year, month, day, hours, minutes, seconds
    )
}

/// Convert days since Unix epoch (1970-01-01) to (year, month, day).
pub fn days_to_ymd(days: u64) -> (u64, u64, u64) {
    let mut y = 1970;
    let mut remaining = days;

    loop {
        let days_in_year = if is_leap_year(y) { 366 } else { 365 };
        if remaining < days_in_year {
            break;
        }
        remaining -= days_in_year;
        y += 1;
    }

    let days_in_months = if is_leap_year(y) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    };

    let mut m = 0;
    for (i, &dim) in days_in_months.iter().enumerate() {
        if remaining < dim {
            m = i + 1;
            break;
        }
        remaining -= dim;
    }

    (y, m as u64, remaining + 1)
}

/// Check if a year is a leap year.
pub fn is_leap_year(y: u64) -> bool {
    (y.is_multiple_of(4) && !y.is_multiple_of(100)) || y.is_multiple_of(400)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_glob_match_patterns() {
        assert!(glob_match("*", "anything"));
        assert!(glob_match("github/*", "github/create_issue"));
        assert!(glob_match("github/*", "github/list_repos"));
        assert!(!glob_match("github/*", "slack/send_message"));
        assert!(glob_match("*/query_*", "database/query_users"));
        assert!(glob_match("?ello", "hello"));
        assert!(!glob_match("?ello", "jello_world"));
        assert!(glob_match("delete_*", "delete_users"));
    }

    #[test]
    fn test_iso8601_format() {
        let ts = now_iso8601();
        // Should match format YYYY-MM-DDTHH:MM:SSZ
        assert!(ts.ends_with('Z'));
        assert_eq!(ts.len(), 20);
        assert_eq!(&ts[4..5], "-");
        assert_eq!(&ts[7..8], "-");
        assert_eq!(&ts[10..11], "T");
    }

    #[test]
    fn test_leap_year() {
        assert!(is_leap_year(2000));
        assert!(is_leap_year(2024));
        assert!(!is_leap_year(1900));
        assert!(!is_leap_year(2023));
    }

    #[test]
    fn test_days_to_ymd_epoch() {
        // Day 0 = 1970-01-01
        assert_eq!(days_to_ymd(0), (1970, 1, 1));
    }
}
